def revenue_by_city(df):
    return (df.assign(revenue=df.quantity * df.price)
        .groupby('city', as_index=False).revenue.sum()
        .sort_values(['revenue', 'city'], ascending=[False, True])
        .reset_index(drop=True))

def conversion_rate(df):
    visits = df.visits.sum()
    return float(df.purchases.sum() / visits) if visits else 0.0

def customer_summary(df):
    return (df.assign(revenue=df.quantity * df.price)
        .groupby('customer_id', as_index=False)
        .agg(orders=('order_id', 'nunique'), revenue=('revenue', 'sum'))
        .sort_values('customer_id'))

def select_values(df):
    values = df.value.to_numpy(dtype=float)
    return values[values > 10] * 2

