def audit_orders(df):
    clean = df.drop_duplicates('order_id').dropna(subset=['city', 'price', 'quantity'])
    clean = clean.loc[(clean.price >= 0) & (clean.quantity > 0) & (clean.status == 'paid')]
    return (clean.assign(city=clean.city.str.strip().str.title(), revenue=clean.quantity * clean.price)
        .groupby('city', as_index=False).agg(revenue=('revenue', 'sum'), orders=('order_id', 'nunique'))
        .sort_values(['revenue', 'city'], ascending=[False, True]))
